package com.asmj.marketplace.jobs;
import java.time.Instant; import java.time.LocalDateTime; import java.util.*; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document;
@Document(collection="job_applications")
public class JobApplication {
 @Id private String id; private String jobId; private String candidateUserId; private String candidateName; private String candidateEmail; private String candidateMobile; private String resumeUrl; private String coverLetter; private String status="APPLIED"; private String employerNotes; private List<InterviewRound> interviews=new ArrayList<>(); private String offerLetterUrl; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now();
 public static class InterviewRound { private String roundName; private LocalDateTime scheduledAt; private String mode; private String meetingLink; private String location; private String interviewer; private String feedback; private Integer rating; private String result="PENDING"; public String getRoundName(){return roundName;} public void setRoundName(String v){roundName=v;} public LocalDateTime getScheduledAt(){return scheduledAt;} public void setScheduledAt(LocalDateTime v){scheduledAt=v;} public String getMode(){return mode;} public void setMode(String v){mode=v;} public String getMeetingLink(){return meetingLink;} public void setMeetingLink(String v){meetingLink=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public String getInterviewer(){return interviewer;} public void setInterviewer(String v){interviewer=v;} public String getFeedback(){return feedback;} public void setFeedback(String v){feedback=v;} public Integer getRating(){return rating;} public void setRating(Integer v){rating=v;} public String getResult(){return result;} public void setResult(String v){result=v;} }
 public String getId(){return id;} public void setId(String v){id=v;} public String getJobId(){return jobId;} public void setJobId(String v){jobId=v;} public String getCandidateUserId(){return candidateUserId;} public void setCandidateUserId(String v){candidateUserId=v;} public String getCandidateName(){return candidateName;} public void setCandidateName(String v){candidateName=v;} public String getCandidateEmail(){return candidateEmail;} public void setCandidateEmail(String v){candidateEmail=v;} public String getCandidateMobile(){return candidateMobile;} public void setCandidateMobile(String v){candidateMobile=v;} public String getResumeUrl(){return resumeUrl;} public void setResumeUrl(String v){resumeUrl=v;} public String getCoverLetter(){return coverLetter;} public void setCoverLetter(String v){coverLetter=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getEmployerNotes(){return employerNotes;} public void setEmployerNotes(String v){employerNotes=v;} public List<InterviewRound> getInterviews(){return interviews;} public void setInterviews(List<InterviewRound> v){interviews=v;} public String getOfferLetterUrl(){return offerLetterUrl;} public void setOfferLetterUrl(String v){offerLetterUrl=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;}
}
